// Perceptual colour tables for the spectrogram (RESTYLE Phase 2): magma (the default), inferno and
// viridis, 256 entries each, precomputed (colormaps.cpp is generated by
// tools/python/make_colormaps.py). Part of the theme: the theme chooses the default.
#pragma once

#include "gui/spectrogram_image.h" // ColourTable.

namespace psyight {

enum class Colormap { magma, inferno, viridis };

const ColourTable &colormap_table(Colormap map);
inline const char *colormap_name(Colormap map) {
    return map == Colormap::magma ? "Magma" : map == Colormap::inferno ? "Inferno" : "Viridis";
}
// The name in the settings file (io/user_settings.h).
inline const char *colormap_id(Colormap map) {
    return map == Colormap::magma ? "magma" : map == Colormap::inferno ? "inferno" : "viridis";
}

} // namespace psyight
